<script setup lang="ts">
import { ref, onMounted, onUnmounted, nextTick, computed, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useUserStore } from "@/stores/user.ts";
import { useMessageStore } from "@/stores/message.ts";
import { useCurrentInstance } from "@/util";
import {
  GetConversationList,
  GetMessageList,
  GetNewMessages,
  PostSendMessage,
  PostReadMessage,
  GetCreateConversation,
  ParseMessageConversation,
  ParseMessage,
} from "@/apis/message.ts";
import { GetUserInfo } from "@/apis/user.ts";
import {
  type MessageConversationView,
  type MessageView,
  MessageConversationTypeSystem,
  MessageConversationTypeSystemDirect,
  MessageConversationTypePrivate,
} from "@/types/message.ts";
import type { CodeResult } from "@/types/request";
import { GetAvatarUrl, HandleImageError } from "@/util/avatar.ts";
import { formatSeparatorTime } from "@/util/time.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

/** Max message content length, must match backend messageMaxContentLength (2000) */
const MESSAGE_MAX_LENGTH = 2000;

/**
 * 系统消息合并会话的虚拟 id。
 * 后端把「系统消息」(type=2 全局广播) 与「系统通知」(type=3 定向) 作为两条会话返回，
 * 前端在侧栏合并为单一条目展示，选中时用此哨兵 id 标识，加载时分别拉取两个来源并按时间归并。
 * 取负值以区别于真实会话 id 与 temp id（temp 从 -1 递减）。
 */
const SYSTEM_MERGED_CONV_ID = -9007199254740991;

/** 发送模式：'enter' = Enter发送(Shift+Enter换行)，'shift_enter' = Shift+Enter发送(Enter换行) */
const SEND_MODE_STORAGE_KEY = "message_send_mode";
type SendMode = "enter" | "shift_enter";
const sendMode = ref<SendMode>("enter");

const { isMobile } = useBreakpoint();
// 移动端：列表/聊天切换状态。true 表示当前显示聊天区，false 表示显示会话列表
const mobileShowChat = ref(false);

/** 从 localStorage 加载发送模式 */
const loadSendMode = () => {
  const saved = localStorage.getItem(SEND_MODE_STORAGE_KEY);
  if (saved === "enter" || saved === "shift_enter") {
    sendMode.value = saved;
  }
};

/** 切换发送模式并持久化 */
const toggleSendMode = () => {
  sendMode.value = sendMode.value === "enter" ? "shift_enter" : "enter";
  localStorage.setItem(SEND_MODE_STORAGE_KEY, sendMode.value);
};

/** 输入框 placeholder，根据发送模式动态显示 */
const inputPlaceholder = computed(() => {
  if (sendMode.value === "enter") {
    return `输入消息，按 Enter 发送，Shift+Enter 换行（最多 ${MESSAGE_MAX_LENGTH} 字）`;
  }
  return `输入消息，按 Shift+Enter 发送，Enter 换行（最多 ${MESSAGE_MAX_LENGTH} 字）`;
});

const { globalProperties } = useCurrentInstance();
const route = useRoute();
const router = useRouter();
const userStore = useUserStore();
const messageStore = useMessageStore();

// Self avatar
const selfAvatarUrl = computed(() => GetAvatarUrl(userStore.getUsername, ""));

// State
const conversations = ref<MessageConversationView[]>([]);
const selectedConvId = ref<number>(0);
const messages = ref<MessageView[]>([]);
const inputContent = ref("");
const loadingMessages = ref(false);
const sendingMessage = ref(false);
const loadingOlder = ref(false);
const hasMoreMessages = ref(true);
const messagesContainer = ref<HTMLElement | null>(null);
const searchKeyword = ref("");

// 系统合并会话的两个底层来源（type=2 广播 / type=3 定向），各自独立分页与读跟踪
const broadcastMessages = ref<MessageView[]>([]);
const directMessages = ref<MessageView[]>([]);
const broadcastHasMore = ref(true);
const directHasMore = ref(true);

// 输入区域 ref，用于附加原生 keydown 监听器
const inputAreaRef = ref<HTMLElement | null>(null);
let nativeTextarea: HTMLTextAreaElement | null = null;

// New message dialog
const showNewDialog = ref(false);
const newDialogUsername = ref("");
const lookingUpUser = ref(false);
let nextTempId = -1;

// Polling
const MSG_POLL_INTERVAL = 3000; // 3s for new messages in active conv
let msgPollTimer: ReturnType<typeof setInterval> | null = null;

const selectedConv = computed(() => {
  return mergedConversations.value.find((c) => c.id === selectedConvId.value) || null;
});

const isSystemConv = computed(() => {
  const t = selectedConv.value?.type;
  return t === MessageConversationTypeSystem || t === MessageConversationTypeSystemDirect;
});

const isTempConv = computed(() => {
  return selectedConv.value?.isTemp === true;
});

/** 当前选中的是否为合并后的系统会话 */
const isMergedSystemConv = computed(() => selectedConvId.value === SYSTEM_MERGED_CONV_ID);

/** 取底层广播会话（type=2，虚拟 id=0） */
const broadcastConv = computed(() =>
  conversations.value.find((c) => c.id === 0 && c.type === MessageConversationTypeSystem) || null
);

/** 取底层定向通知会话（type=3）的真实 id；不存在返回 0 */
const directConvId = computed(() => {
  const c = conversations.value.find((c) => c.type === MessageConversationTypeSystemDirect) || null;
  return c?.id || 0;
});

/**
 * 把广播(type=2)与定向(type=3)两条系统会话合并为单一条目展示。
 * unread 相加；预览/时间取两者中较新者。
 */
const mergedConversations = computed<MessageConversationView[]>(() => {
  const b = broadcastConv.value;
  const d = conversations.value.find((c) => c.type === MessageConversationTypeSystemDirect) || null;
  const rest = conversations.value.filter(
    (c) => !(c.id === 0 && c.type === MessageConversationTypeSystem) && c.type !== MessageConversationTypeSystemDirect
  );
  if (!b && !d) return rest;
  const bUnread = b?.unreadCount ?? 0;
  const dUnread = d?.unreadCount ?? 0;
  const bMs = b?.lastMessageTimeMs ?? 0;
  const dMs = d?.lastMessageTimeMs ?? 0;
  const newer = bMs >= dMs ? b : d;
  const merged: MessageConversationView = {
    id: SYSTEM_MERGED_CONV_ID,
    type: MessageConversationTypeSystem,
    peerId: 0,
    peerUsername: "system",
    peerNickname: "系统消息",
    peerEmail: "",
    avatarUrl: "",
    lastMessage: newer?.lastMessage || "暂无消息",
    lastMessageTime: newer?.lastMessageTime || "",
    lastMessageTimeMs: Math.max(bMs, dMs),
    unreadCount: bUnread + dUnread,
  };
  // 系统会话始终置顶
  return [merged, ...rest];
});

/** 按时间稳定归并两个来源，重建展示用 messages 数组 */
const rebuildMergedMessages = () => {
  const combined = [...broadcastMessages.value, ...directMessages.value];
  combined.sort((a, b) => a.createTimeMs - b.createTimeMs);
  messages.value = combined;
  hasMoreMessages.value = broadcastHasMore.value || directHasMore.value;
};

const filteredConversations = computed(() => {
  if (!searchKeyword.value.trim()) return mergedConversations.value;
  const kw = searchKeyword.value.toLowerCase();
  return mergedConversations.value.filter(
    (c) =>
      c.peerNickname.toLowerCase().includes(kw) ||
      c.peerUsername.toLowerCase().includes(kw)
  );
});

// Load conversation list (preserves temp conversations)
const loadConversations = async () => {
  try {
    const res = await GetConversationList();
    if (res.code === 0) {
      const list = (res.data || []).map((item) => ParseMessageConversation(item));
      const prevSelected = selectedConvId.value;
      // Keep any temp conversations (negative ids) that aren't yet in the server list
      const tempConvs = conversations.value.filter((c) => c.isTemp);
      // Remove temp convs that now have a real conversation (matched by username)
      const validTempConvs = tempConvs.filter(
        (tc) => !list.find((c: MessageConversationView) => c.peerUsername === tc.peerUsername && c.type === MessageConversationTypePrivate)
      );
      conversations.value = [...validTempConvs, ...list];
      if (prevSelected > 0 && !conversations.value.find((c: MessageConversationView) => c.id === prevSelected)) {
        selectedConvId.value = 0;
        messages.value = [];
      }
    }
  } catch (e) {
    console.error("Failed to load conversations:", e);
  }
};

// Load messages for selected conversation
const loadMessages = async (convId: number, beforeId: number = 0) => {
  if (convId === SYSTEM_MERGED_CONV_ID) {
    if (beforeId === 0) return loadMergedMessages();
    return loadOlderMergedMessages();
  }
  if (loadingMessages.value) return;
  loadingMessages.value = true;
  try {
    const res = await GetMessageList(convId, beforeId);
    if (res.code === 0) {
      const newMsgs = (res.data || []).map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      if (beforeId === 0) {
        messages.value = newMsgs;
        hasMoreMessages.value = newMsgs.length >= 50;
        nextTick(() => scrollToBottom());
      } else {
        const prevScrollHeight = messagesContainer.value?.scrollHeight || 0;
        messages.value = [...newMsgs, ...messages.value];
        hasMoreMessages.value = newMsgs.length >= 50;
        nextTick(() => {
          if (messagesContainer.value) {
            messagesContainer.value.scrollTop =
              messagesContainer.value.scrollHeight - prevScrollHeight;
          }
        });
      }
    }
  } catch (e) {
    console.error("Failed to load messages:", e);
  } finally {
    loadingMessages.value = false;
  }
};

// Load older messages (scroll up)
const loadOlderMessages = async () => {
  if (loadingOlder.value || !hasMoreMessages.value || messages.value.length === 0) return;
  if (isTempConv.value) return;
  if (isMergedSystemConv.value) return loadOlderMergedMessages();
  loadingOlder.value = true;
  const firstId = messages.value[0].id;
  try {
    const res = await GetMessageList(selectedConvId.value, firstId);
    if (res.code === 0) {
      const newMsgs = (res.data || []).map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      const prevScrollHeight = messagesContainer.value?.scrollHeight || 0;
      messages.value = [...newMsgs, ...messages.value];
      hasMoreMessages.value = newMsgs.length >= 50;
      nextTick(() => {
        if (messagesContainer.value) {
          messagesContainer.value.scrollTop =
            messagesContainer.value.scrollHeight - prevScrollHeight;
        }
      });
    }
  } catch (e) {
    console.error("Failed to load older messages:", e);
  } finally {
    loadingOlder.value = false;
  }
};

// ─── 系统合并会话：双源加载/分页/轮询 ───────────────────────────────
// 广播(type=2, conv 0) 与定向(type=3, 真实 conv id) 各自独立分页，
// 展示时按 createTimeMs 稳定归并为一条时间线。

// 初始加载合并系统会话（两个来源均拉取最新一页）
const loadMergedMessages = async () => {
  if (loadingMessages.value) return;
  loadingMessages.value = true;
  broadcastMessages.value = [];
  directMessages.value = [];
  broadcastHasMore.value = true;
  directHasMore.value = true;
  const bConvExists = !!broadcastConv.value;
  const dId = directConvId.value;
  try {
    const [bRes, dRes] = await Promise.all([
      bConvExists ? GetMessageList(0, 0) : Promise.resolve(null),
      dId > 0 ? GetMessageList(dId, 0) : Promise.resolve(null),
    ]);
    if (bRes?.code === 0) {
      broadcastMessages.value = (bRes.data || []).map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      broadcastHasMore.value = broadcastMessages.value.length >= 50;
    } else {
      broadcastHasMore.value = false;
    }
    if (dRes?.code === 0) {
      directMessages.value = (dRes.data || []).map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      directHasMore.value = directMessages.value.length >= 50;
    } else {
      directHasMore.value = false;
    }
    rebuildMergedMessages();
    nextTick(() => scrollToBottom());
  } catch (e) {
    console.error("Failed to load system messages:", e);
  } finally {
    loadingMessages.value = false;
  }
};

// 加载更早的系统消息（两个来源各自用自身的首条 id 翻页，再归并）
const loadOlderMergedMessages = async () => {
  if (loadingOlder.value) return;
  if (!hasMoreMessages.value) return;
  if (broadcastMessages.value.length === 0 && directMessages.value.length === 0) return;
  loadingOlder.value = true;
  const dId = directConvId.value;
  const bFirst = broadcastMessages.value[0]?.id || 0;
  const dFirst = directMessages.value[0]?.id || 0;
  try {
    const [bRes, dRes] = await Promise.all([
      bFirst > 0 ? GetMessageList(0, bFirst) : Promise.resolve(null),
      dId > 0 && dFirst > 0 ? GetMessageList(dId, dFirst) : Promise.resolve(null),
    ]);
    if (bRes?.code === 0) {
      const older = (bRes.data || []).map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      broadcastMessages.value = [...older, ...broadcastMessages.value];
      broadcastHasMore.value = older.length >= 50;
    }
    if (dRes?.code === 0) {
      const older = (dRes.data || []).map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      directMessages.value = [...older, ...directMessages.value];
      directHasMore.value = older.length >= 50;
    }
    const prevScrollHeight = messagesContainer.value?.scrollHeight || 0;
    rebuildMergedMessages();
    nextTick(() => {
      if (messagesContainer.value) {
        messagesContainer.value.scrollTop =
          messagesContainer.value.scrollHeight - prevScrollHeight;
      }
    });
  } catch (e) {
    console.error("Failed to load older system messages:", e);
  } finally {
    loadingOlder.value = false;
  }
};

// 轮询合并系统会话的新消息；若某来源在选中后才出现（初始为空），补做一次初始加载
const pollMergedNewMessages = async () => {
  const bConvExists = !!broadcastConv.value;
  const dId = directConvId.value;
  const bHas = broadcastMessages.value.length > 0;
  const dHas = directMessages.value.length > 0;
  const bLast = bHas ? broadcastMessages.value[broadcastMessages.value.length - 1].id : 0;
  const dLast = dHas ? directMessages.value[directMessages.value.length - 1].id : 0;
  if (!bConvExists && dId <= 0) return;
  try {
    const [bRes, dRes] = await Promise.all([
      bConvExists ? (bHas ? GetNewMessages(0, bLast) : GetMessageList(0, 0)) : Promise.resolve(null),
      dId > 0 ? (dHas ? GetNewMessages(dId, dLast) : GetMessageList(dId, 0)) : Promise.resolve(null),
    ]);
    let added = 0;
    if (bRes?.code === 0 && bRes.data?.length) {
      const newer = bRes.data.map((item) => ParseMessage(item, userStore.getUserId));
      if (bHas) {
        broadcastMessages.value = [...broadcastMessages.value, ...newer];
      } else {
        broadcastMessages.value = newer;
        broadcastHasMore.value = newer.length >= 50;
      }
      added += newer.length;
    }
    if (dRes?.code === 0 && dRes.data?.length) {
      const newer = dRes.data.map((item) => ParseMessage(item, userStore.getUserId));
      if (dHas) {
        directMessages.value = [...directMessages.value, ...newer];
      } else {
        directMessages.value = newer;
        directHasMore.value = newer.length >= 50;
      }
      added += newer.length;
    }
    if (added > 0) {
      rebuildMergedMessages();
      nextTick(() => scrollToBottom());
    }
  } catch (e) {
    // silent
  }
};

// Poll for new messages in active conversation
const pollNewMessages = async () => {
  if (isMergedSystemConv.value) return pollMergedNewMessages();
  if (selectedConvId.value < 0 || isTempConv.value) return;
  if (!selectedConv.value) return;
  if (messages.value.length === 0) return;
  const lastId = messages.value[messages.value.length - 1].id;
  try {
    const res = await GetNewMessages(selectedConvId.value, lastId);
    if (res.code === 0 && res.data && res.data.length > 0) {
      const newMsgs = res.data.map((item) =>
        ParseMessage(item, userStore.getUserId)
      );
      messages.value = [...messages.value, ...newMsgs];
      const conv = conversations.value.find((c) => c.id === selectedConvId.value);
      if (conv) conv.unreadCount = 0;
      nextTick(() => scrollToBottom());
    }
  } catch (e) {
    // silent
  }
};

// Scroll to bottom of messages
const scrollToBottom = () => {
  nextTick(() => {
    if (messagesContainer.value) {
      messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
    }
  });
};

// Handle scroll - load more when near top
const onScroll = () => {
  if (!messagesContainer.value) return;
  if (messagesContainer.value.scrollTop < 50) {
    loadOlderMessages();
  }
};

// Select conversation
const selectConversation = async (conv: MessageConversationView) => {
  selectedConvId.value = conv.id;
  messages.value = [];
  inputContent.value = "";
  hasMoreMessages.value = true;
  // 即时本地更新：清未读并减少全局角标
  const cleared = conv.unreadCount;
  conv.unreadCount = 0;
  // 合并系统会话：需同时清两个底层来源，并分别标记已读
  if (conv.id === SYSTEM_MERGED_CONV_ID) {
    const b = broadcastConv.value;
    const d = conversations.value.find((c) => c.type === MessageConversationTypeSystemDirect) || null;
    if (b) b.unreadCount = 0;
    if (d) d.unreadCount = 0;
    if (cleared > 0) {
      messageStore.decrementUnread(cleared);
    }
    broadcastMessages.value = [];
    directMessages.value = [];
    if (isMobile.value) {
      mobileShowChat.value = true;
    }
    await loadMergedMessages();
    try {
      await PostReadMessage(0);
    } catch (e) {
      // silent
    }
    const dId = directConvId.value;
    if (dId > 0) {
      try {
        await PostReadMessage(dId);
      } catch (e) {
        // silent
      }
    }
    return;
  }
  if (cleared > 0) {
    messageStore.decrementUnread(cleared);
  }
  if (conv.isTemp) {
    // Temp conversation has no messages in DB yet
    hasMoreMessages.value = false;
    if (isMobile.value) {
      mobileShowChat.value = true;
    }
    return;
  }
  await loadMessages(conv.id);
  try {
    await PostReadMessage(conv.id);
  } catch (e) {
    // silent
  }
  // 移动端：选中会话后切到聊天视图
  if (isMobile.value) {
    mobileShowChat.value = true;
  }
};

// 移动端：返回会话列表
const handleMobileBack = () => {
  mobileShowChat.value = false;
};

/** 用户信息查询（/user/info）返回体的最小声明：只包含新建私信会话用到的字段 */
interface UserInfoLookup {
  id: number;
  username: string;
  nickname?: string;
  email?: string;
}

// Open a new conversation with a given username (from dialog or URL param)
// Returns true on success, false on failure
const openNewConversation = async (username: string): Promise<boolean> => {
  const trimmed = username.trim();
  if (!trimmed) return false;
  // Don't allow messaging yourself
  if (trimmed.toLowerCase() === userStore.getUsername.toLowerCase()) {
    globalProperties.$message.warning("不能给自己发消息");
    return false;
  }
  // Check if already in conversation list (existing real or temp conv)
  const existing = conversations.value.find(
    (c) => c.type === MessageConversationTypePrivate && c.peerUsername.toLowerCase() === trimmed.toLowerCase()
  );
  if (existing) {
    await selectConversation(existing);
    return true;
  }
  // Look up user info
  lookingUpUser.value = true;
  try {
    const res: CodeResult<{ user: UserInfoLookup }> = await GetUserInfo(trimmed);
    if (res.code === 0 && res.data?.user) {
      const user = res.data.user;
      // Check again after lookup (race condition)
      const existingAfter = conversations.value.find(
        (c) => c.type === MessageConversationTypePrivate && c.peerUsername.toLowerCase() === user.username.toLowerCase()
      );
      if (existingAfter) {
        await selectConversation(existingAfter);
        return true;
      }
      // Create temp conversation
      const tempId = nextTempId--;
      const tempConv: MessageConversationView = {
        id: tempId,
        type: MessageConversationTypePrivate,
        peerId: user.id,
        peerUsername: user.username,
        peerNickname: user.nickname || user.username,
        peerEmail: user.email || "",
        avatarUrl: GetAvatarUrl(user.username, user.email || ""),
        lastMessage: "",
        lastMessageTime: "",
        unreadCount: 0,
        isTemp: true,
      };
      conversations.value = [tempConv, ...conversations.value];
      await selectConversation(tempConv);
      return true;
    } else {
      globalProperties.$message.error("用户不存在");
      return false;
    }
  } catch (e) {
    globalProperties.$message.error("用户不存在");
    return false;
  } finally {
    lookingUpUser.value = false;
  }
};

// Confirm new message dialog
const confirmNewDialog = async () => {
  const username = newDialogUsername.value.trim();
  if (!username) {
    globalProperties.$message.warning("请输入用户名");
    return;
  }
  const ok = await openNewConversation(username);
  if (ok) {
    showNewDialog.value = false;
    newDialogUsername.value = "";
  }
};

// Send message
const sendMessage = async () => {
  const content = inputContent.value.trim();
  if (!content || sendingMessage.value) return;
  if (!selectedConv.value || isSystemConv.value) return;
  sendingMessage.value = true;
  try {
    let targetConvId = selectedConvId.value;
    // If this is a temp conversation, first create the real conversation
    if (isTempConv.value && selectedConv.value) {
      const createRes = await GetCreateConversation(selectedConv.value.peerUsername);
      if (createRes.code === 0 && createRes.data?.conversation_id) {
        const realConvId = createRes.data.conversation_id;
        const tempId = selectedConvId.value;
        // Remove temp from list, refresh to get real conversation
        conversations.value = conversations.value.filter((c) => c.id !== tempId);
        await loadConversations();
        // Select the real conversation
        const realConv = conversations.value.find((c) => c.id === realConvId);
        if (realConv) {
          selectedConvId.value = realConvId;
          targetConvId = realConvId;
          messages.value = [];
          hasMoreMessages.value = true;
        } else {
          // Should not happen, but just in case
          sendingMessage.value = false;
          globalProperties.$message.error("创建会话失败");
          return;
        }
      } else {
        sendingMessage.value = false;
        globalProperties.$message.error("创建会话失败");
        return;
      }
    }
    const res = await PostSendMessage(targetConvId, content);
    if (res.code === 0) {
      inputContent.value = "";
      // For newly created conv, load messages from scratch
      if (isTempConv.value === false && messages.value.length === 0) {
        await loadMessages(targetConvId);
      } else {
        await pollNewMessages();
      }
      loadConversations();
    } else {
      globalProperties.$message.error("发送失败");
    }
  } catch (e) {
    globalProperties.$message.error("发送失败");
  } finally {
    sendingMessage.value = false;
  }
};

const handleKeydown = (e: KeyboardEvent) => {
  // 忽略输入法组合过程中的按键，避免干扰中文输入
  if (e.isComposing) return;
  if (e.key !== "Enter") return;

  if (sendMode.value === "enter") {
    // Enter 发送，Shift+Enter 换行
    if (!e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  } else {
    // Shift+Enter 发送，Enter 换行
    if (e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  }
};

/** 附加原生 keydown 监听器到内部 textarea 元素 */
const attachKeyListener = () => {
  detachKeyListener();
  nextTick(() => {
    if (inputAreaRef.value) {
      nativeTextarea = inputAreaRef.value.querySelector("textarea");
      if (nativeTextarea) {
        nativeTextarea.addEventListener("keydown", handleKeydown);
      }
    }
  });
};

/** 分离原生 keydown 监听器 */
const detachKeyListener = () => {
  if (nativeTextarea) {
    nativeTextarea.removeEventListener("keydown", handleKeydown);
    nativeTextarea = null;
  }
};

// Format time for message groups
const formatMessageTime = (msg: MessageView, index: number) => {
  if (msg.createTimeMs === 0) return "";
  if (index === 0) {
    return formatSepTime(new Date(msg.createTimeMs));
  }
  const prev = messages.value[index - 1];
  if (prev.createTimeMs === 0) return "";
  if (msg.createTimeMs - prev.createTimeMs > 5 * 60 * 1000) {
    return formatSepTime(new Date(msg.createTimeMs));
  }
  return "";
};

const formatSepTime = (d: Date): string => {
  return formatSeparatorTime(d);
};

/** 系统定向通知内容的 JSON 结构 */
interface DiscussNotificationContent {
  type: string;
  text: string;
  discuss_id: number;
  comment_id: number;
}

/** 解析系统定向通知内容，失败返回 null */
const parseNotificationContent = (content: string): DiscussNotificationContent | null => {
  try {
    const parsed = JSON.parse(content);
    if (parsed && typeof parsed.type === "string" && typeof parsed.text === "string") {
      return parsed as DiscussNotificationContent;
    }
  } catch {
    // 非合法 JSON，忽略
  }
  return null;
};

/** 点击通知链接，跳转到对应讨论并定位评论 */
const handleClickNotificationLink = (notification: DiscussNotificationContent) => {
  if (notification.discuss_id) {
    const hash = notification.comment_id ? `#comment-${notification.comment_id}` : "";
    router.push(`/discuss/${notification.discuss_id}${hash}`);
  }
};

// Polling: refresh conv list every N polls to pick up new conversations (e.g. system messages)
const CONV_LIST_REFRESH_INTERVAL = 5; // refresh every 5 polls = 15 seconds
let pollTickCount = 0;

// Start polling for new messages in active conversation.
// Pauses when the page is hidden (visibilitychange) to save bandwidth.
const startPolling = () => {
  stopPolling();
  pollTickCount = 0;
  const tick = () => {
    if (document.visibilityState === "hidden") return;
    pollNewMessages();
    messageStore.fetchUnreadCount();
    pollTickCount++;
    if (pollTickCount >= CONV_LIST_REFRESH_INTERVAL) {
      pollTickCount = 0;
      loadConversations();
    }
  };
  msgPollTimer = setInterval(tick, MSG_POLL_INTERVAL);
};

const stopPolling = () => {
  if (msgPollTimer) {
    clearInterval(msgPollTimer);
    msgPollTimer = null;
  }
};

// Resume a single poll cycle when the page becomes visible again
const onMsgVisibilityChange = () => {
  if (document.visibilityState === "visible" && selectedConvId.value !== 0) {
    pollNewMessages();
    messageStore.fetchUnreadCount();
  }
};

// 监听会话切换，重新附加键盘监听器（textarea 可能在 v-if 切换时被重建）
watch(
  () => selectedConvId.value,
  () => {
    attachKeyListener();
  }
);

onMounted(async () => {
  messageStore.isMessageViewActive = true;
  messageStore.fetchUnreadCount();
  document.addEventListener("visibilitychange", onMsgVisibilityChange);
  // 加载用户保存的发送模式
  loadSendMode();
  await loadConversations();

  // Handle URL query param ?username=xxx (from profile page "send message" link)
  const usernameParam = route.query.username as string | undefined;
  if (usernameParam) {
    // Open conversation FIRST, then clear the param — if the user lookup fails,
    // the param remains so the caller can retry.
    await openNewConversation(usernameParam);
    router.replace({ name: "message" });
  } else if (mergedConversations.value.length > 0) {
    await selectConversation(mergedConversations.value[0]);
  }
  startPolling();
});

onUnmounted(() => {
  stopPolling();
  messageStore.isMessageViewActive = false;
  document.removeEventListener("visibilitychange", onMsgVisibilityChange);
  messageStore.fetchUnreadCount();
  // 分离原生键盘监听器
  detachKeyListener();
});
</script>

